package com.mtajchert.flocket.core.model

/** Stable local id of a configured host (generated by the app, never shown to users). */
@JvmInline
value class HostId(
    val value: String,
)

/**
 * Which herdr-core the app talks to: a configured host plus an optional `hc` session name
 * (`hc connect --session <name>`; null = the host's default session).
 */
data class CoreEndpoint(
    val hostId: HostId,
    val session: String? = null,
)

/**
 * A terminal's address inside one core, exactly as the core reports it: `t7`, `t1b` (base-30, not
 * decimal!) or `rohan/t7` for a terminal on a federated machine. Opaque: never parse the number,
 * never strip the machine prefix. See protocol/SPEC.md §6.1.
 */
@JvmInline
value class TerminalAddress(
    val value: String,
) {
    /** Machine prefix for federated terminals (`rohan` in `rohan/t7`), null for local ones. */
    val machine: String? get() = value.substringBeforeLast('/', missingDelimiterValue = "").ifEmpty { null }

    val isRemote: Boolean get() = machine != null

    override fun toString(): String = value
}

/** App-wide identity of a terminal: the endpoint it lives behind plus its core address. */
data class TerminalRef(
    val endpoint: CoreEndpoint,
    val address: TerminalAddress,
)
